using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Graph.Roommates;

internal sealed class PaddedCompletionDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Partial components of the Mertens range-two proof; the full theorem remains open.",
        H("PaddedCompletion"), Blocks(
            Describe.Lean(DescribeId.Create("closing-coordinate"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/Roommates/PaddedCompletion.closing_coordinate"),
                H("closing_coordinate"), StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The exact buffer coordinate is target+6 for a left exterior request and target-m for a right exterior request. The full integer-coordinate identity is retained for source-cycle transport."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("oldranking"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/Roommates/PaddedCompletion.oldRanking"),
                H("oldRanking"), StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Preserve the old rankings on both separated pieces."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("old-nonblocking"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/Roommates/PaddedCompletion.old_nonblocking"),
                H("old_nonblocking"), StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Every old--old edge has its original stability test. The six-site gap excludes cross-piece edges; translation preserves each same-piece rank comparison."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("closingrequester"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/Roommates/PaddedCompletion.ClosingRequester"),
                H("ClosingRequester"), StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Select exterior nonzero requests of one certified word. No old single is reclassified as a request."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("closingrequest"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/Roommates/PaddedCompletion.closingRequest"),
                H("closingRequest"), StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Map left exterior targets to buffer sites 4,5 and right exterior targets to 0,1. This retains the four distinct possible exterior targets even at m=1."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("closing-request-completion"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/Roommates/PaddedCompletion.closing_request_completion"),
                H("closing_request_completion"), StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every length, actual closing requests are injective and avoid central sites. The existing sixteen layouts fulfill all requests with a genuine involution and only central new singles. Full source-cycle stability, including m=1 extra buffer wrap edges, and injectivity on closed preference profiles are still missing."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("oldposition"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/Roommates/PaddedCompletion.oldPosition"),
                H("oldPosition"), StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Place the left word at coordinates 0 through m-1 and the right word at m+6 through m+6+k-1."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("oldoffset"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/Roommates/PaddedCompletion.oldOffset"),
                H("oldOffset"), StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Preserve every chosen displacement in the two input certificates, including zero for singles."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("oldtarget"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/Roommates/PaddedCompletion.oldTarget"),
                H("oldTarget"), StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Targets are integers, including all exterior requests. No quotient or truncation removes possible collisions."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("requester"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/Roommates/PaddedCompletion.Requester"),
                H("Requester"), StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Select the actual old vertices whose nonzero requests enter the six-site gap."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("request"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/Roommates/PaddedCompletion.request"),
                H("request"), StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Translate each actual gap target to its buffer coordinate in Fin 6."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("old-target-injective"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/Roommates/PaddedCompletion.old_target_injective"),
                H("old_target_injective"), StatementSource.FromLean(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Full integer-target injectivity holds across both old pieces. Within one piece use its certificate; across pieces the left targets are at most m+1 and the right targets at least m+4."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("padded-request-completion"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/Roommates/PaddedCompletion.padded_request_completion"),
